from __future__ import annotations


_FEED_MILL_STYLES = r'''
    .fm-tabs{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 16px}.fm-tab{border:1px solid var(--line);background:#fff;color:#405247;border-radius:9px;padding:8px 12px;font-size:12px;font-weight:800;cursor:pointer}.fm-tab.active{background:var(--brand);border-color:var(--brand);color:#fff}.fm-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:16px}.fm-kpi{background:var(--card);border:1px solid var(--line);border-radius:13px;padding:15px;box-shadow:var(--shadow)}.fm-kpi .fm-value{font-size:22px;font-weight:850;margin-top:5px}.fm-kpi .fm-note{font-size:10px;color:var(--muted);margin-top:3px}.fm-alert{border-radius:11px;padding:12px 14px;margin:0 0 16px;background:#fff3dc;border:1px solid #efd39c;color:#714a00;font-size:12px}.fm-grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fm-recipe{border:1px solid var(--line);border-radius:12px;padding:14px;margin-bottom:10px;background:#fbfcfb}.fm-recipe-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.fm-recipe-title{font-weight:850;font-size:15px}.fm-recipe-output{font-size:11px;color:var(--muted);margin-top:3px}.fm-ingredients{margin-top:10px;border-top:1px solid var(--line);padding-top:8px}.fm-ingredient{display:flex;justify-content:space-between;gap:12px;padding:4px 0;font-size:12px}.fm-empty{padding:22px;text-align:center;color:var(--muted)}.fm-section-title{font-size:15px;font-weight:850;margin:0}.fm-status{font-size:10px;font-weight:800;padding:4px 7px;border-radius:999px;background:#edf3ee}.fm-status.in_transit{background:#fff0d3;color:#745000}.fm-status.divergent{background:#fde3e3;color:#8f2626}.fm-status.received{background:#e5f4e8;color:#276237}.fm-status.cancelled{background:#eee;color:#555}.fm-loading{padding:30px;text-align:center;color:var(--muted)}.fm-purpose-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:16px}.fm-purpose{border:1px solid var(--line);border-radius:11px;padding:12px;background:#fbfcfb}.fm-purpose b{display:block;font-size:14px}.fm-purpose span{font-size:11px;color:var(--muted)}
    @media(max-width:900px){.fm-summary{grid-template-columns:1fr 1fr}.fm-grid2{grid-template-columns:1fr}.fm-purpose-grid{grid-template-columns:1fr 1fr}}@media(max-width:650px){.fm-summary{grid-template-columns:1fr}.fm-purpose-grid{grid-template-columns:1fr}}
'''.strip()


_FEED_MILL_JS = r'''
let feedMillWorkspace=null;
let feedMillTab='overview';
const FM_TRANSFER_STATUS={in_transit:'Em trânsito',received:'Recebida',divergent:'Com divergência',cancelled:'Cancelada'};
const FM_ENTRY_LABELS={receipt:'Entrada',adjustment:'Correção gerencial',transfer_receipt:'Recebimento de transferência'};
function fmTransferStatus(v){return FM_TRANSFER_STATUS[v]||statusLabel(v)}
function fmEntryLabel(v){return FM_ENTRY_LABELS[v]||String(v||'-').replaceAll('_',' ')}
function fmTabs(){const tabs=[['overview','Visão da fábrica'],['inventory','Estoque'],['consumptions','Consumos'],['productions','Produções'],['recipes','Fórmulas'],['transfers','Transferências'],['entries','Entradas']];return `<div class="fm-tabs">${tabs.map(([id,label])=>`<button class="fm-tab ${feedMillTab===id?'active':''}" onclick="setFeedMillTab('${id}')">${label}</button>`).join('')}</div>`}
function setFeedMillTab(tab){feedMillTab=tab;const m=(state.modules||[]).find(x=>x.code==='feed_mill');if(m)renderFeedMillContent(m)}
async function loadFeedMillWorkspace(force=false){if(feedMillWorkspace&&!force)return feedMillWorkspace;const [workspace,consumptions]=await Promise.all([api('/v1/dashboard/feed-mill'),api('/v1/dashboard/stock/consumptions')]);workspace.consumption_data=consumptions;feedMillWorkspace=workspace;return feedMillWorkspace}
function fmTable(headers,rows){return rows.length?table(headers,rows):'<div class="fm-empty">Nenhum registro.</div>'}
function renderFeedMillOverview(d){const s=d.summary||{};const alert=s.zero_raw_material_count?`<div class="fm-alert"><b>Atenção ao abastecimento:</b> ${fmt.format(s.zero_raw_material_count)} matéria(s)-prima(s) sem saldo: ${esc((s.zero_raw_materials||[]).join(', '))}.</div>`:'';const stockRows=(d.inventory||[]).filter(x=>Number(x.quantity)>0).slice(0,12).map(x=>`<tr><td>${esc(x.unit_code)}</td><td>${esc(x.product_name)}</td><td>${fmt.format(x.quantity)} ${esc(x.base_unit)}</td><td>${money.format(x.avg_unit_cost)}</td><td>${money.format(x.total_value)}</td></tr>`);const prodRows=(d.productions||[]).slice(0,8).map(x=>`<tr><td>${dateLabel(x.created_at)}</td><td>${esc(x.unit_code)}</td><td>${esc(x.recipe_name)}</td><td>${fmt.format(x.batch_count)}</td><td>${fmt.format(x.output_quantity)} ${esc(x.output_unit)}</td><td>${money.format(x.total_material_cost)}</td></tr>`);const consumptionRows=(d.consumption_data?.consumptions||[]).slice(0,8).map(x=>`<tr><td>${dateLabel(x.created_at)}</td><td>${esc(x.unit_code)}</td><td>${esc(x.product_name)}</td><td>${fmt.format(x.quantity)} ${esc(x.base_unit)}</td><td>${esc(x.purpose_label)}</td><td>${esc(x.context_label||'-')}</td></tr>`);const transitRows=(d.transfers||[]).filter(x=>x.status==='in_transit').slice(0,8).map(x=>`<tr><td>${dateLabel(x.dispatched_at)}</td><td>${esc(x.source_unit_code)} → ${esc(x.destination_unit_code)}</td><td>${esc(x.product_name)}</td><td>${fmt.format(x.quantity)} ${esc(x.base_unit)}</td><td>${money.format(x.total_value)}</td></tr>`);return `${fmTabs()}<div class="fm-summary"><div class="fm-kpi"><div class="label">Estoque total</div><div class="fm-value">${money.format(s.inventory_value||0)}</div><div class="fm-note">estoque físico das fazendas</div></div><div class="fm-kpi"><div class="label">Matérias-primas</div><div class="fm-value">${money.format(s.raw_material_value||0)}</div></div><div class="fm-kpi"><div class="label">Ração pronta</div><div class="fm-value">${money.format(s.finished_good_value||0)}</div></div><div class="fm-kpi"><div class="label">Fórmulas ativas</div><div class="fm-value">${fmt.format(s.active_recipes||0)}</div></div><div class="fm-kpi"><div class="label">Produções recentes</div><div class="fm-value">${fmt.format(s.production_count||0)}</div></div><div class="fm-kpi"><div class="label">Transferências em trânsito</div><div class="fm-value">${fmt.format(s.transfers_in_transit||0)}</div></div></div>${alert}<div class="fm-grid2"><div class="panel"><div class="panel-head"><h2>Estoque com saldo</h2><button class="btn small secondary" onclick="setFeedMillTab('inventory')">Ver tudo</button></div><div class="table-wrap">${fmTable(['Fazenda','Produto','Saldo','Custo médio','Valor'],stockRows)}</div></div><div class="panel"><div class="panel-head"><h2>Produções recentes</h2><button class="btn small secondary" onclick="setFeedMillTab('productions')">Ver tudo</button></div><div class="table-wrap">${fmTable(['Data','Fazenda','Fórmula','Batidas','Produção','Custo'],prodRows)}</div></div></div><div class="panel"><div class="panel-head"><h2>Consumos informados no campo</h2><button class="btn small secondary" onclick="setFeedMillTab('consumptions')">Ver tudo</button></div><div class="table-wrap">${fmTable(['Data','Fazenda','Produto','Quantidade','Finalidade','Contexto'],consumptionRows)}</div></div><div class="panel"><div class="panel-head"><h2>Transferências em trânsito</h2></div><div class="table-wrap">${fmTable(['Saída','Rota','Produto','Quantidade','Valor'],transitRows)}</div></div>`}
function renderFeedMillInventory(d){const rows=(d.inventory||[]).map(x=>`<tr><td>${esc(x.unit_code)}</td><td>${esc(x.product_name)}</td><td>${x.product_type==='raw_material'?'Matéria-prima':'Produto acabado'}</td><td>${fmt.format(x.quantity)} ${esc(x.base_unit)}</td><td>${money.format(x.avg_unit_cost)}</td><td>${money.format(x.total_value)}</td></tr>`);return `${fmTabs()}<div class="panel"><div class="panel-head"><h2>Estoque por fazenda</h2><span class="hint">O saldo pertence à fazenda. O uso baixa daqui e registra a finalidade.</span></div><div class="table-wrap">${fmTable(['Fazenda','Produto','Tipo','Saldo','Custo médio','Valor'],rows)}</div></div>`}
function renderFeedMillConsumptions(d){const c=d.consumption_data||{summary:{},by_purpose:[],by_product:[],consumptions:[]};const purposes=(c.by_purpose||[]).map(x=>`<div class="fm-purpose"><b>${esc(x.purpose_label)}</b><span>${fmt.format(x.records)} registro(s) · ${money.format(x.total_value)}</span></div>`).join('');const rows=(c.consumptions||[]).map(x=>`<tr><td>${dateLabel(x.created_at)}</td><td>${esc(x.unit_code)}</td><td>${esc(x.product_name)}</td><td>${fmt.format(x.quantity)} ${esc(x.base_unit)}</td><td>${esc(x.purpose_label)}</td><td>${esc(x.context_label||'-')}</td><td>${money.format(x.total_value)}</td><td class="source">${esc(x.source_original||'-')}</td></tr>`);return `${fmTabs()}<div class="fm-summary"><div class="fm-kpi"><div class="label">Consumos registrados</div><div class="fm-value">${fmt.format(c.summary?.records||0)}</div></div><div class="fm-kpi"><div class="label">Valor consumido</div><div class="fm-value">${money.format(c.summary?.total_value||0)}</div></div></div>${purposes?`<div class="fm-purpose-grid">${purposes}</div>`:''}<div class="panel"><div class="panel-head"><h2>Uso real dos produtos</h2><span class="hint">A pessoa informa o que fez no Telegram; o Campo e Dados organiza a finalidade e o custo.</span></div><div class="table-wrap">${fmTable(['Data','Fazenda','Produto','Quantidade','Finalidade','Contexto','Custo','Informação original'],rows)}</div></div>`}
function renderFeedMillProductions(d){const rows=(d.productions||[]).map(x=>`<tr><td>${dateLabel(x.created_at)}</td><td>${esc(x.unit_code)}</td><td>${esc(x.recipe_name)}</td><td>${fmt.format(x.batch_count)}</td><td>${fmt.format(x.output_quantity)} ${esc(x.output_unit)}</td><td>${money.format(x.total_material_cost)}</td><td>${money.format(x.output_unit_cost)}</td></tr>`);return `${fmTabs()}<div class="panel"><div class="panel-head"><h2>Histórico de produções</h2></div><div class="table-wrap">${fmTable(['Data','Fazenda','Fórmula','Batidas','Produção','Custo total','Custo unitário'],rows)}</div></div>`}
function renderFeedMillRecipes(d){const rows=(d.recipes||[]);return `${fmTabs()}<div class="panel"><div class="panel-head"><h2>Fórmulas</h2><span class="hint">Composição registrada por batida.</span></div><div class="panel-body">${rows.length?rows.map(r=>`<div class="fm-recipe"><div class="fm-recipe-head"><div><div class="fm-recipe-title">${esc(r.name)}</div><div class="fm-recipe-output">1 batida produz ${fmt.format(r.output_quantity_per_batch)} ${esc(r.output_unit)} de ${esc(r.output_product_name)}</div></div><span class="fm-status">${r.active?'Ativa':'Inativa'}</span></div><div class="fm-ingredients">${r.ingredients.map(i=>`<div class="fm-ingredient"><span>${esc(i.product_name)}</span><b>${fmt.format(i.quantity_per_batch)} ${esc(i.base_unit)}</b></div>`).join('')}</div></div>`).join(''):'<div class="fm-empty">Nenhuma fórmula cadastrada.</div>'}</div></div>`}
function renderFeedMillTransfers(d){const rows=(d.transfers||[]).map(x=>`<tr><td>${dateLabel(x.dispatched_at)}</td><td>${esc(x.source_unit_code)} → ${esc(x.destination_unit_code)}</td><td>${esc(x.product_name)}</td><td>${fmt.format(x.quantity)} ${esc(x.base_unit)}</td><td>${x.received_quantity===null?'-':fmt.format(x.received_quantity)+' '+esc(x.base_unit)}</td><td>${x.divergence_quantity===null?'-':fmt.format(x.divergence_quantity)+' '+esc(x.base_unit)}</td><td>${money.format(x.total_value)}</td><td><span class="fm-status ${esc(x.status)}">${esc(fmTransferStatus(x.status))}</span></td></tr>`);return `${fmTabs()}<div class="panel"><div class="panel-head"><h2>Transferências entre fazendas</h2><span class="hint">Transferência existe quando o estoque muda de fazenda.</span></div><div class="table-wrap">${fmTable(['Saída','Rota','Produto','Enviado','Recebido','Diferença','Valor','Status'],rows)}</div></div>`}
function renderFeedMillEntries(d){const rows=(d.entries||[]).map(x=>`<tr><td>${dateLabel(x.created_at)}</td><td>${esc(x.unit_code)}</td><td>${esc(x.product_name)}</td><td>${esc(fmEntryLabel(x.movement_type))}</td><td>${fmt.format(x.quantity)} ${esc(x.base_unit)}</td><td>${money.format(x.unit_cost)}</td><td>${money.format(x.total_value)}</td></tr>`);return `${fmTabs()}<div class="panel"><div class="panel-head"><h2>Entradas físicas recentes</h2><span class="hint">A operação entra pelo Telegram. Correções gerenciais permanecem auditadas.</span></div><div class="table-wrap">${fmTable(['Data','Fazenda','Produto','Origem','Quantidade','Custo unitário','Valor'],rows)}</div></div>`}
function renderFeedMillContent(m){const body=document.getElementById('modulePageBody');if(!body)return;const d=feedMillWorkspace;if(!d){body.innerHTML='<div class="fm-loading">Carregando Fábrica de Ração...</div>';return}if(feedMillTab==='inventory')body.innerHTML=renderFeedMillInventory(d);else if(feedMillTab==='consumptions')body.innerHTML=renderFeedMillConsumptions(d);else if(feedMillTab==='productions')body.innerHTML=renderFeedMillProductions(d);else if(feedMillTab==='recipes')body.innerHTML=renderFeedMillRecipes(d);else if(feedMillTab==='transfers')body.innerHTML=renderFeedMillTransfers(d);else if(feedMillTab==='entries')body.innerHTML=renderFeedMillEntries(d);else body.innerHTML=renderFeedMillOverview(d)}
async function renderFeedMillPage(m,force=false){document.getElementById('modulePageTitle').textContent='Fábrica de Ração';document.getElementById('modulePageSubtitle').textContent='Estoque da fazenda, produção, consumo, fórmulas e transferências — gestão sem burocracia no campo.';const update=document.querySelector('#page-module .title-row .btn');if(update)update.onclick=async()=>{try{await refresh();await renderFeedMillPage(m,true)}catch(e){showAlert(e.message,'err')}};const body=document.getElementById('modulePageBody');if(body)body.innerHTML='<div class="fm-loading">Carregando Fábrica de Ração...</div>';try{await loadFeedMillWorkspace(force);renderFeedMillContent(m)}catch(e){if(body)body.innerHTML=`<div class="alert err show">${esc(e.message)}</div>`}}
const _campoRenderModulePage=renderModulePage;
renderModulePage=function(m){if(m?.code==='feed_mill'){renderFeedMillPage(m);return}_campoRenderModulePage(m)};
'''.strip()


def enhance_dashboard_feed_mill_ui(html: str) -> str:
    html = html.replace("</style>", _FEED_MILL_STYLES + "\n  </style>", 1)
    html = html.replace("</body>", f"<script>{_FEED_MILL_JS}</script></body>", 1)
    return html
